import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Ubuntu (No Custom Domain)","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/ubuntu-no-custom-domain.md","filePath":"getting-started/ubuntu-no-custom-domain.md"}'),r={name:"getting-started/ubuntu-no-custom-domain.md"};function o(n,e,p,d,l,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="ubuntu-no-custom-domain" tabindex="-1">Ubuntu (No Custom Domain) <a class="header-anchor" href="#ubuntu-no-custom-domain" aria-label="Permalink to &quot;Ubuntu (No Custom Domain)&quot;">​</a></h1><p>Tradeboard can be installed on an Ubuntu desktop or laptop by preparing the system, downloading the source code, configuring broker credentials, and launching the application locally.</p><p>For traders using an Indian broker, static IP configuration is now mandatory for retail algo trading under SEBI regulations. This must be completed before using transactional broker APIs for live order placement.</p><h3 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h3><p>Make sure the following are available on your Ubuntu system before you begin.</p><p>Python 3.12 or newer (Tradeboard requires <code>&gt;=3.12</code>)</p><p>Git</p><p>uv package manager</p><p>Visual Studio Code or any code editor</p><p>Internet connection</p><p>Broker API credentials</p><p>For Indian brokers, a static IPv4 address</p><p>Node.js is not required. The repository ships the pre-built React frontend in <code>frontend/dist</code>.</p><h3 id="step-1-create-a-project-folder" tabindex="-1">Step 1 Create a Project Folder <a class="header-anchor" href="#step-1-create-a-project-folder" aria-label="Permalink to &quot;Step 1 Create a Project Folder&quot;">​</a></h3><p>Create a new folder on your Ubuntu desktop or laptop for the Tradeboard project. The folder name can be anything you prefer.</p><p>Open this folder in your code editor.</p><h3 id="step-2-check-required-software" tabindex="-1">Step 2 Check Required Software <a class="header-anchor" href="#step-2-check-required-software" aria-label="Permalink to &quot;Step 2 Check Required Software&quot;">​</a></h3><p>Open the terminal inside the project folder and confirm the versions:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # must report 3.12 or newer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>If <code>uv</code> is missing, install it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or, on PEP 668 systems such as Ubuntu 24.04:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -LsSf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://astral.sh/uv/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>If <code>python3</code> reports anything older than 3.12, install a newer interpreter before continuing. Tradeboard will not start on 3.11 or below.</p><h3 id="step-3-download-the-tradeboard-source-code" tabindex="-1">Step 3 Download the Tradeboard Source Code <a class="header-anchor" href="#step-3-download-the-tradeboard-source-code" aria-label="Permalink to &quot;Step 3 Download the Tradeboard Source Code&quot;">​</a></h3><p>Clone the repository into your project folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/wesoftcorp/tradeboard-docs.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tradeboard</span></span></code></pre></div><h3 id="step-4-create-the-environment-file" tabindex="-1">Step 4 Create the Environment File <a class="header-anchor" href="#step-4-create-the-environment-file" aria-label="Permalink to &quot;Step 4 Create the Environment File&quot;">​</a></h3><p>Copy the sample environment file to <code>.env</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .sample.env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>This file holds your broker settings and credentials. Never copy <code>.sample.env</code> over an existing <code>.env</code> on a working installation: it discards your credentials and replaces <code>API_KEY_PEPPER</code> and <code>FERNET_SALT</code>, which makes stored passwords and encrypted broker tokens unrecoverable.</p><h3 id="step-5-configure-broker-credentials" tabindex="-1">Step 5 Configure Broker Credentials <a class="header-anchor" href="#step-5-configure-broker-credentials" aria-label="Permalink to &quot;Step 5 Configure Broker Credentials&quot;">​</a></h3><p>Open the environment file and update the required values.</p><p>You will typically need to enter the following details.</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_API_KEY&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_API_SECRET&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">REDIRECT_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/&lt;broker&gt;/callback&#39;</span></span></code></pre></div><p>Replace <code>&lt;broker&gt;</code> with your broker&#39;s key, for example <code>http://127.0.0.1:5000/zerodha/callback</code>.</p><p>Leave <code>APP_KEY</code>, <code>API_KEY_PEPPER</code> and <code>FERNET_SALT</code> at their <code>TRADEBOARD_PLACEHOLDER_...</code> values. Tradeboard replaces them with fresh random secrets on first start and prints a one-time <code>[Tradeboard first-run setup]</code> message when it does.</p><p>The exact values and process depend on the broker you use.</p><h3 id="step-6-generate-api-credentials-from-your-broker" tabindex="-1">Step 6 Generate API Credentials from Your Broker <a class="header-anchor" href="#step-6-generate-api-credentials-from-your-broker" aria-label="Permalink to &quot;Step 6 Generate API Credentials from Your Broker&quot;">​</a></h3><p>Log in to your broker’s developer portal and create an app for API access.</p><p>Depending on the broker, you may need to provide an app name, redirect URL, and other broker specific information.</p><p>After the app is created, copy the API key and API secret and paste them into the environment file.</p><h3 id="step-7-configure-static-ip-for-indian-brokers" tabindex="-1">Step 7 Configure Static IP for Indian Brokers <a class="header-anchor" href="#step-7-configure-static-ip-for-indian-brokers" aria-label="Permalink to &quot;Step 7 Configure Static IP for Indian Brokers&quot;">​</a></h3><p>If you are using an Indian broker, static IP setup is mandatory for retail algo trading under SEBI regulations.</p><p>Your broker must whitelist the fixed IP address from which your orders originate. This applies to transactional APIs used for placing, modifying, cancelling, basket, or split orders.</p><p>Important points to note</p><p>Orders must originate from a whitelisted static IP</p><p>This requirement applies from 1 April 2026 for retail algo traders using broker APIs</p><p>Most brokers provide primary and secondary IP slots</p><p>IP changes are generally allowed only once per week</p><p>Home internet connections often use dynamic IPs and are not reliable for this purpose</p><p>A static IPv4 address is required because brokers do not generally support IPv6 whitelisting</p><p>For desktop users, one option is to request a static IP from the internet service provider. Another option is to use a VPS, which usually includes a static IP by default.</p><p>More details are available on the <a href="./../static-ip">Tradeboard static IP page</a>.</p><h3 id="step-8-save-changes-properly" tabindex="-1">Step 8 Save Changes Properly <a class="header-anchor" href="#step-8-save-changes-properly" aria-label="Permalink to &quot;Step 8 Save Changes Properly&quot;">​</a></h3><p>After updating the environment file, save it carefully.</p><p>Whenever you change the API key, API secret, or related broker settings, save the file and restart the application so the changes take effect.</p><h3 id="step-9-start-tradeboard" tabindex="-1">Step 9 Start Tradeboard <a class="header-anchor" href="#step-9-start-tradeboard" aria-label="Permalink to &quot;Step 9 Start Tradeboard&quot;">​</a></h3><p>Launch Tradeboard from the project directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.py</span></span></code></pre></div><p>On the first run, <code>uv</code> creates the <code>.venv</code> virtual environment and installs every dependency from <code>pyproject.toml</code>, so the first launch takes several minutes. Later launches start immediately.</p><p>When the server is ready it prints a banner with the live endpoints: the web app on <code>http://127.0.0.1:5000</code> and the WebSocket proxy on <code>ws://127.0.0.1:8765</code>. Open <a href="http://127.0.0.1:5000" target="_blank" rel="noreferrer">http://127.0.0.1:5000</a> in your browser.</p><p>Press <code>Ctrl+C</code> in the terminal to stop Tradeboard.</p><h3 id="step-10-complete-first-time-account-setup" tabindex="-1">Step 10 Complete First Time Account Setup <a class="header-anchor" href="#step-10-complete-first-time-account-setup" aria-label="Permalink to &quot;Step 10 Complete First Time Account Setup&quot;">​</a></h3><p>When Tradeboard opens for the first time, you will be taken to the setup screen.</p><p>Create your account using the required details.</p><p>Username</p><p>Email address</p><p>Password</p><p>Password confirmation</p><p>Use a strong password that meets the platform requirements.</p><h3 id="step-11-log-in-to-tradeboard" tabindex="-1">Step 11 Log In to Tradeboard <a class="header-anchor" href="#step-11-log-in-to-tradeboard" aria-label="Permalink to &quot;Step 11 Log In to Tradeboard&quot;">​</a></h3><p>After the initial account setup, log in using your Tradeboard credentials.</p><p>This is your application login and is separate from your broker authentication.</p><h3 id="step-12-connect-your-broker-account" tabindex="-1">Step 12 Connect Your Broker Account <a class="header-anchor" href="#step-12-connect-your-broker-account" aria-label="Permalink to &quot;Step 12 Connect Your Broker Account&quot;">​</a></h3><p>After logging in, connect your broker account from within Tradeboard.</p><p>Broker login is usually a manual step. In the workflow described, the broker session remains active until the next day at 3:00 AM, after which you must log in again.</p><h3 id="step-13-wait-for-platform-initialization" tabindex="-1">Step 13 Wait for Platform Initialization <a class="header-anchor" href="#step-13-wait-for-platform-initialization" aria-label="Permalink to &quot;Step 13 Wait for Platform Initialization&quot;">​</a></h3><p>After connecting the broker, Tradeboard opens the main dashboard.</p><p>At this stage, the platform may begin downloading the master contract. Wait until this process finishes completely.</p><p>You should only proceed when the dashboard shows that the system is ready.</p><p>Do not start automation until the platform indicates readiness.</p><h3 id="common-mistakes-to-avoid" tabindex="-1">Common Mistakes to Avoid <a class="header-anchor" href="#common-mistakes-to-avoid" aria-label="Permalink to &quot;Common Mistakes to Avoid&quot;">​</a></h3><p>Do not forget to save the environment file after editing credentials</p><p>Do not forget to restart the application after changing broker settings</p><p>Do not use a dynamic home IP for Indian broker transactional APIs</p><p>Do not begin automation before the dashboard is fully ready</p><p>Do not assume the same credential setup process applies to every broker</p><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>Installing Tradeboard on Ubuntu Desktop involves preparing the system, downloading the project, configuring the environment file, adding broker credentials, setting up static IP when required, launching the application, and completing the first time login flow.</p><p>For Indian brokers, static IP compliance is now an essential part of setup and must be completed before live API based trading.</p>`,89)])])}const k=a(r,[["render",o]]);export{u as __pageData,k as default};
